-- DomainFits Dynamic CMS — MySQL 8 / MariaDB 10.6+
-- Create/select an empty database in your hosting panel, then import this file.
-- No default admin account or third-party IDs are created. See README-BN.md.
SET NAMES utf8mb4;
SET time_zone = '+00:00';

CREATE TABLE IF NOT EXISTS admin_users (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  email VARCHAR(254) NOT NULL,
  display_name VARCHAR(120) NOT NULL,
  password_hash VARCHAR(255) NOT NULL,
  status ENUM('active','disabled') NOT NULL DEFAULT 'active',
  last_login_at DATETIME NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id), UNIQUE KEY uq_admin_email (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS admin_roles (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  role_key VARCHAR(64) NOT NULL,
  label VARCHAR(120) NOT NULL,
  description VARCHAR(255) NOT NULL DEFAULT '',
  PRIMARY KEY (id), UNIQUE KEY uq_admin_role_key (role_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS admin_permissions (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  permission_key VARCHAR(64) NOT NULL,
  label VARCHAR(120) NOT NULL,
  PRIMARY KEY (id), UNIQUE KEY uq_admin_permission_key (permission_key)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS admin_login_limits (
  ip_hash CHAR(64) NOT NULL,
  failures SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  window_started_at DATETIME NOT NULL,
  locked_until DATETIME NULL,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (ip_hash), KEY idx_login_lock (locked_until)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS admin_user_roles (
  user_id BIGINT UNSIGNED NOT NULL,
  role_id BIGINT UNSIGNED NOT NULL,
  PRIMARY KEY (user_id, role_id),
  CONSTRAINT fk_user_role_user FOREIGN KEY (user_id) REFERENCES admin_users(id) ON DELETE CASCADE,
  CONSTRAINT fk_user_role_role FOREIGN KEY (role_id) REFERENCES admin_roles(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS admin_role_permissions (
  role_id BIGINT UNSIGNED NOT NULL,
  permission_id BIGINT UNSIGNED NOT NULL,
  PRIMARY KEY (role_id, permission_id),
  CONSTRAINT fk_role_permission_role FOREIGN KEY (role_id) REFERENCES admin_roles(id) ON DELETE CASCADE,
  CONSTRAINT fk_role_permission_permission FOREIGN KEY (permission_id) REFERENCES admin_permissions(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS admin_audit_logs (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  admin_id BIGINT UNSIGNED NULL,
  action_key VARCHAR(80) NOT NULL,
  entity_type VARCHAR(80) NOT NULL DEFAULT '',
  entity_id VARCHAR(80) NOT NULL DEFAULT '',
  detail VARCHAR(500) NOT NULL DEFAULT '',
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id), KEY idx_audit_admin_date (admin_id, created_at), KEY idx_audit_entity (entity_type, entity_id),
  CONSTRAINT fk_audit_admin FOREIGN KEY (admin_id) REFERENCES admin_users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS site_settings (
  setting_key VARCHAR(100) NOT NULL,
  value_json JSON NOT NULL,
  is_public TINYINT(1) NOT NULL DEFAULT 1,
  updated_by BIGINT UNSIGNED NULL,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (setting_key), KEY idx_setting_public (is_public)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS navigation_items (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  menu_location ENUM('header','footer') NOT NULL,
  group_label VARCHAR(80) NOT NULL DEFAULT '',
  label VARCHAR(100) NOT NULL,
  href VARCHAR(500) NOT NULL,
  sort_order INT NOT NULL DEFAULT 0,
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id), UNIQUE KEY uq_nav_location_label (menu_location, label), KEY idx_nav_order (menu_location, sort_order, is_active)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS blog_posts (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  slug VARCHAR(180) NOT NULL,
  legacy_file VARCHAR(64) NULL,
  legacy_day SMALLINT UNSIGNED NULL,
  title VARCHAR(255) NOT NULL,
  excerpt VARCHAR(500) NOT NULL DEFAULT '',
  body_html MEDIUMTEXT NOT NULL,
  category VARCHAR(120) NOT NULL DEFAULT '',
  tags_json JSON NOT NULL,
  featured_image VARCHAR(500) NOT NULL DEFAULT '',
  featured_image_alt VARCHAR(255) NOT NULL DEFAULT '',
  seo_title VARCHAR(255) NOT NULL DEFAULT '',
  seo_description VARCHAR(320) NOT NULL DEFAULT '',
  canonical_url VARCHAR(500) NOT NULL DEFAULT '',
  og_image VARCHAR(500) NOT NULL DEFAULT '',
  schema_type VARCHAR(40) NOT NULL DEFAULT 'BlogPosting',
  status ENUM('draft','review','scheduled','published','archived') NOT NULL DEFAULT 'draft',
  published_at DATETIME NULL,
  scheduled_at DATETIME NULL,
  is_featured TINYINT(1) NOT NULL DEFAULT 0,
  publication_reviewed TINYINT(1) NOT NULL DEFAULT 0,
  publication_reviewed_at DATETIME NULL,
  publication_reviewed_by BIGINT UNSIGNED NULL,
  view_count BIGINT UNSIGNED NOT NULL DEFAULT 0,
  created_by BIGINT UNSIGNED NULL,
  updated_by BIGINT UNSIGNED NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id), UNIQUE KEY uq_post_slug (slug), UNIQUE KEY uq_post_legacy_file (legacy_file),
  KEY idx_post_status_date (status, published_at), KEY idx_post_category_date (category, status, published_at),
  CONSTRAINT fk_post_creator FOREIGN KEY (created_by) REFERENCES admin_users(id) ON DELETE SET NULL,
  CONSTRAINT fk_post_updater FOREIGN KEY (updated_by) REFERENCES admin_users(id) ON DELETE SET NULL,
  CONSTRAINT fk_post_reviewed_by FOREIGN KEY (publication_reviewed_by) REFERENCES admin_users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS categories (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  name VARCHAR(120) NOT NULL,
  slug VARCHAR(140) NOT NULL,
  created_by BIGINT UNSIGNED NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id), UNIQUE KEY uq_categories_name (name), UNIQUE KEY uq_categories_slug (slug),
  CONSTRAINT fk_content_category_creator FOREIGN KEY (created_by) REFERENCES admin_users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS blog_post_categories (
  post_id BIGINT UNSIGNED NOT NULL,
  category_id BIGINT UNSIGNED NOT NULL,
  PRIMARY KEY (post_id, category_id),
  KEY idx_post_categories_category (category_id, post_id),
  CONSTRAINT fk_post_categories_post FOREIGN KEY (post_id) REFERENCES blog_posts(id) ON DELETE CASCADE,
  CONSTRAINT fk_post_categories_category FOREIGN KEY (category_id) REFERENCES categories(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS site_pages (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  slug VARCHAR(180) NOT NULL,
  legacy_file VARCHAR(64) NULL,
  title VARCHAR(255) NOT NULL,
  excerpt VARCHAR(500) NOT NULL DEFAULT '',
  content_html MEDIUMTEXT NOT NULL,
  seo_title VARCHAR(255) NOT NULL DEFAULT '',
  seo_description VARCHAR(320) NOT NULL DEFAULT '',
  canonical_url VARCHAR(500) NOT NULL DEFAULT '',
  og_image VARCHAR(500) NOT NULL DEFAULT '',
  status ENUM('draft','published','archived') NOT NULL DEFAULT 'draft',
  noindex TINYINT(1) NOT NULL DEFAULT 0,
  created_by BIGINT UNSIGNED NULL,
  updated_by BIGINT UNSIGNED NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id), UNIQUE KEY uq_page_slug (slug), UNIQUE KEY uq_page_legacy_file (legacy_file), KEY idx_page_status (status),
  CONSTRAINT fk_page_creator FOREIGN KEY (created_by) REFERENCES admin_users(id) ON DELETE SET NULL,
  CONSTRAINT fk_page_updater FOREIGN KEY (updated_by) REFERENCES admin_users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS wordbank_categories (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  category_key VARCHAR(60) NOT NULL,
  label VARCHAR(120) NOT NULL,
  description VARCHAR(255) NOT NULL DEFAULT '',
  detection_keywords_json JSON NOT NULL,
  preferred_words_json JSON NOT NULL,
  display_order INT NOT NULL DEFAULT 0,
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  updated_by BIGINT UNSIGNED NULL,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id), UNIQUE KEY uq_word_category_key (category_key), KEY idx_word_category_order (is_active, display_order)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS wordbank_terms (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  word VARCHAR(48) NOT NULL,
  term_type ENUM('curated','brandable','long_partner') NOT NULL DEFAULT 'curated',
  english_reviewed TINYINT(1) NOT NULL DEFAULT 0,
  category_id BIGINT UNSIGNED NULL,
  partner_length TINYINT UNSIGNED NULL,
  verification_status ENUM('unverified','reviewed') NOT NULL DEFAULT 'unverified',
  source ENUM('seed','manual','gemini') NOT NULL DEFAULT 'seed',
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  note VARCHAR(255) NOT NULL DEFAULT '',
  created_by BIGINT UNSIGNED NULL,
  updated_by BIGINT UNSIGNED NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id), UNIQUE KEY uq_word_type (word, term_type), KEY idx_word_active_type (is_active, term_type, word),
  KEY idx_word_category_length (category_id, partner_length, is_active),
  CONSTRAINT fk_word_category FOREIGN KEY (category_id) REFERENCES wordbank_categories(id) ON DELETE SET NULL,
  CONSTRAINT fk_word_creator FOREIGN KEY (created_by) REFERENCES admin_users(id) ON DELETE SET NULL,
  CONSTRAINT fk_word_updater FOREIGN KEY (updated_by) REFERENCES admin_users(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS ad_slots (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  placement VARCHAR(64) NOT NULL,
  label VARCHAR(120) NOT NULL DEFAULT '',
  publisher_id VARCHAR(32) NOT NULL DEFAULT '',
  ad_unit_id VARCHAR(32) NOT NULL DEFAULT '',
  ad_format ENUM('auto','rectangle','horizontal','vertical') NOT NULL DEFAULT 'auto',
  size_preset ENUM('responsive','leaderboard','mobile_banner','medium_rectangle','billboard','skyscraper') NOT NULL DEFAULT 'responsive',
  show_desktop TINYINT(1) NOT NULL DEFAULT 1,
  show_tablet TINYINT(1) NOT NULL DEFAULT 1,
  show_mobile TINYINT(1) NOT NULL DEFAULT 1,
  custom_markup MEDIUMTEXT NULL,
  is_enabled TINYINT(1) NOT NULL DEFAULT 0,
  updated_by BIGINT UNSIGNED NULL,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id), UNIQUE KEY uq_ad_placement (placement)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS contact_messages (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  name VARCHAR(100) NOT NULL,
  email VARCHAR(254) NOT NULL,
  topic VARCHAR(100) NOT NULL DEFAULT '',
  subject VARCHAR(200) NOT NULL DEFAULT '',
  message TEXT NOT NULL,
  status ENUM('unread','read','replied','archived') NOT NULL DEFAULT 'unread',
  submitted_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id), KEY idx_contact_status_date (status, submitted_at), KEY idx_contact_email (email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS public_rate_limits (
  key_hash CHAR(64) NOT NULL,
  window_started_at DATETIME NOT NULL,
  request_count SMALLINT UNSIGNED NOT NULL DEFAULT 0,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (key_hash), KEY idx_rate_window (window_started_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS site_events (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  event_type ENUM('page_view','generator_run') NOT NULL,
  page_path VARCHAR(500) NOT NULL DEFAULT '/',
  visitor_hash CHAR(64) NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id), KEY idx_event_date (created_at, event_type), KEY idx_event_page_date (page_path(191), created_at), KEY idx_event_visitor_date (visitor_hash, created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS affiliate_links (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  slug VARCHAR(120) NOT NULL,
  label VARCHAR(180) NOT NULL,
  destination_url VARCHAR(1000) NOT NULL,
  is_active TINYINT(1) NOT NULL DEFAULT 0,
  created_by BIGINT UNSIGNED NULL,
  updated_by BIGINT UNSIGNED NULL,
  created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id), UNIQUE KEY uq_affiliate_slug (slug), KEY idx_affiliate_active (is_active)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS affiliate_clicks (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  affiliate_link_id BIGINT UNSIGNED NOT NULL,
  visitor_hash CHAR(64) NULL,
  clicked_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id), KEY idx_aff_click_date (clicked_at), KEY idx_aff_click_link_date (affiliate_link_id, clicked_at),
  CONSTRAINT fk_affiliate_click_link FOREIGN KEY (affiliate_link_id) REFERENCES affiliate_links(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;



SELECT r.id, p.id FROM admin_roles r CROSS JOIN admin_permissions p WHERE r.role_key = 'super_admin';
SELECT r.id, p.id FROM admin_roles r JOIN admin_permissions p ON p.permission_key IN ('view_dashboard','manage_posts','manage_pages','manage_wordbank') WHERE r.role_key = 'content_editor';
SELECT r.id, p.id FROM admin_roles r JOIN admin_permissions p ON p.permission_key IN ('view_dashboard','manage_analytics') WHERE r.role_key = 'analyst';

ON DUPLICATE KEY UPDATE setting_key = VALUES(setting_key);





-- Seed vocabulary copied from the unmodified root assets/js/domain-generator-data.js.
ON DUPLICATE KEY UPDATE label=VALUES(label), description=VALUES(description), detection_keywords_json=VALUES(detection_keywords_json), preferred_words_json=VALUES(preferred_words_json), display_order=VALUES(display_order), is_active=1;

-- 1224 unique curated, brandable and long-partner terms. English-review flags start false.

-- Import the existing static content without changing its source files: 32 published posts,
-- with editorial days 31-50 retained as drafts until an explicit CMS review gate is cleared.

-- Seed existing public information pages. Their source HTML remains untouched.

-- Contact form submissions are stored in the CMS inbox; no automatic email provider is configured.


-- Backfill the relational post categories while preserving the legacy category string.
SELECT DISTINCT LEFT(TRIM(category),120),
       CASE WHEN LOWER(TRIM(BOTH '-' FROM REGEXP_REPLACE(TRIM(category),'[^a-zA-Z0-9]+','-'))) = ''
            THEN CONCAT('category-',LEFT(SHA2(TRIM(category),256),12))
            ELSE CONCAT(LEFT(LOWER(TRIM(BOTH '-' FROM REGEXP_REPLACE(TRIM(category),'[^a-zA-Z0-9]+','-'))),120),'-',LEFT(SHA2(TRIM(category),256),8)) END
FROM blog_posts WHERE TRIM(category) <> '';
SELECT p.id, c.id FROM blog_posts p JOIN categories c ON c.name = TRIM(p.category) WHERE TRIM(p.category) <> '';
UPDATE wordbank_terms
SET partner_length = CASE WHEN CHAR_LENGTH(word) BETWEEN 2 AND 6 THEN CHAR_LENGTH(word) ELSE NULL END,
    verification_status = CASE WHEN english_reviewed = 1 THEN 'reviewed' ELSE 'unverified' END;
